def contient_voyelle(mot):
    return any(lettre in "aeiouAEIOU" for lettre in mot)

print(contient_voyelle("rythm"))
print(contient_voyelle("python"))

def tous_presents(elements, collection):
    return all(e in collection for e in elements)

print(tous_presents(["pomme", "kiwi"], ["pomme", "banane", "kiwi", "fraise"]))
print(tous_presents(["pomme", "mangue"], ["pomme", "banane", "kiwi", "fraise"]))
